<script setup lang="ts">
import { computed, nextTick, onMounted, ref, watch } from 'vue';
import { api } from '../api';
import { type Row, forumCategories, resourceCategories, statusNames, exchangeNames, formatTime } from '../../shared/domain';
import Icon from './Icon.vue';
const props = defineProps<{ mode: 'forum' | 'resources'; user: Row | null; manage?: boolean }>();
const emit = defineEmits<{ (event: 'join'): void }>();
const rows = ref<Row[]>([]), own = ref<Row[]>([]), replies = ref<Row[]>([]), exchanges = ref<Row[]>([]), managed = ref<Row[]>([]), managedReplies = ref<Row[]>([]);
const tab = ref(props.manage ? 'moderate' : 'public'), category = ref('全部'), search = ref(''), loading = ref(false), busy = ref(false), error = ref(''), message = ref('');
const modal = ref(''), dialog = ref<HTMLDialogElement | null>(null), form = ref<Row>({}), selected = ref<Row>({}), replyContent = ref('');
const forum = computed(() => props.mode === 'forum');
const staff = computed(() => props.user && ['superadmin', 'admin', 'organizer'].includes(props.user.role));
const categories = computed(() => forum.value ? forumCategories : resourceCategories);
const filtered = computed(() => (tab.value === 'mine' ? own.value : rows.value).filter(row => (category.value === '全部' || row.category === category.value) && [row.title, row.content, row.offering, row.seeking, row.district].join(' ').includes(search.value)));
const availability: Record<string, string> = { available: '可交换', reserved: '交换中', exchanged: '已完成交换', closed: '已关闭' };
let generation = 0;
async function load() {
  const version = ++generation; loading.value = true; error.value = '';
  try {
    const data = await api(forum.value ? '/forum/topics' : '/resources'); if (version !== generation) return; rows.value = data;
    if (props.user) { const mine = await api(forum.value ? '/my/forum' : '/my/resources'); if (version !== generation) return; own.value = mine; }
    if (!forum.value && props.user) { const data = await api('/my/exchanges'); if (version !== generation) return; exchanges.value = data; }
    if (staff.value) { const data = await api(forum.value ? '/admin/forum' : '/admin/resources'); if (version !== generation) return; managed.value = forum.value ? data.topics : data.resources; managedReplies.value = forum.value ? data.replies : data.exchanges; }
  } catch (e) { if (version === generation) error.value = (e as Error).message; } finally { if (version === generation) loading.value = false; }
}
function member() { if (!props.user || props.user.status !== 'approved') { emit('join'); return false; } return true; }
async function open(kind: string, data: Row = {}) { form.value = { ...data }; modal.value = kind; error.value = ''; await nextTick(); if (!dialog.value?.open) dialog.value?.showModal(); }
function close() { if (busy.value) return; dialog.value?.close(); modal.value = ''; }
function create() { if (member()) open(forum.value ? 'topic' : 'resource', forum.value ? { title: '', category: forumCategories[0], content: '' } : { title: '', category: resourceCategories[0], offering: '', seeking: '', district: props.user?.district || '', contact: '' }); }
async function detail(row: Row) {
  selected.value = row; replies.value = []; replyContent.value = '';
  await open(forum.value ? 'topicDetail' : 'resourceDetail');
  if (forum.value) { try { const data = await api('/forum/topics/' + row.id); selected.value = data.topic; replies.value = data.replies; } catch (e) { error.value = (e as Error).message; } }
}
async function act(action: () => Promise<any>, text: string, keep = false) {
  if (busy.value) return; busy.value = true; error.value = '';
  try { await action(); busy.value = false; if (!keep) close(); message.value = text; await load(); if (keep && forum.value) { const data = await api('/forum/topics/' + selected.value.id); selected.value = data.topic; replies.value = data.replies; replyContent.value = ''; } } catch (e) { error.value = (e as Error).message; } finally { busy.value = false; }
}
function review(row: Row, type: string) { open('review', { ...row, endpoint: type, originalStatus: row.status, status: row.status === 'approved' ? 'hidden' : 'approved', note: '' }); }
function changeExchange(row: Row, action: string) { open('confirm', { path: '/exchanges/' + row.id + '/action', body: { action }, text: action === 'confirm' ? '请确认你负责的资源或服务已经实际交付。双方都确认后，交换才会完成。' : action === 'accept' ? '接受后该资源将保留给这位老乡，其他待处理申请会自动关闭。' : action === 'reject' ? '确认拒绝本次交换申请？' : '确认取消尚未接受的交换申请？' }); }
watch([() => props.mode, () => props.user?.id, () => props.manage, () => props.user?.status, () => props.user?.role], () => { ++generation; rows.value = []; own.value = []; managed.value = []; managedReplies.value = []; exchanges.value = []; selected.value = {}; close(); tab.value = props.manage ? 'moderate' : 'public'; category.value = '全部'; search.value = ''; load(); });
onMounted(load);
</script>
<template>
  <section :aria-busy="loading">
    <p v-if="error && !modal" class="form-error" role="alert">{{ error }}</p><p v-if="message" class="status-note" role="status">{{ message }}</p>
    <div class="filterbar hub-toolbar"><div class="chips"><button :class="{ selected: tab === 'public' }" @click="tab = 'public'">{{ forum ? '全部话题' : '资源广场' }}</button><button v-if="user" :class="{ selected: tab === 'mine' }" @click="tab = 'mine'">我的发布</button><button v-if="user && !forum" :class="{ selected: tab === 'exchanges' }" @click="tab = 'exchanges'">我的交换</button><button v-if="staff" :class="{ selected: tab === 'moderate' }" @click="tab = 'moderate'">{{ forum ? '主题与回帖审核' : '资源审核' }}</button></div><button class="primary" @click="create"><Icon name="plus"/>{{ forum ? '发起话题' : '发布交换资源' }}</button></div>
    <template v-if="tab === 'public' || tab === 'mine'"><div class="filterbar"><div class="chips"><button v-for="value in ['全部', ...categories]" :key="value" :class="{ selected: category === value }" @click="category = value">{{ value }}</button></div><label class="search-box"><Icon name="search"/><input v-model="search" :placeholder="forum ? '搜索话题' : '搜索资源、地区'" aria-label="搜索论坛或资源"></label></div><div v-if="!filtered.length" class="empty"><Icon :name="forum ? 'book' : 'people'"/><h3>{{ forum ? '有故事，一起聊' : '你的一技之长，也许正是老乡所需' }}</h3><p>{{ forum ? '分享生活经验，聊聊家乡故事。主题和回帖审核后展示。' : '写清我能提供什么、我需要什么，找到合适的交换伙伴。' }}</p><button class="outline" @click="create">{{ forum ? '发起第一个话题' : '发布一份资源' }}</button></div><div class="cards-grid"><article v-for="row in filtered" :key="row.id" class="post-card"><div class="hub-row"><span class="tag">{{ row.category }}</span><small>{{ tab === 'mine' ? statusNames[row.status] || row.status : forum ? row.replyCount + ' 条回复' : availability[row.availability] }}</small></div><h3><button class="plain" @click="detail(row)">{{ row.title }}</button></h3><p v-if="forum" class="excerpt">{{ row.content }}</p><template v-else><div class="exchange-offer"><small>我能提供</small><p>{{ row.offering }}</p></div><div class="exchange-offer seek"><small>我需要</small><p>{{ row.seeking }}</p></div><p class="meta"><Icon name="pin"/>{{ row.district }}</p></template><p v-if="tab === 'mine' && row.reviewNote" class="form-tip">审核说明：{{ row.reviewNote }}</p><div class="card-footer"><span>{{ row.authorName }} · {{ formatTime(row.createdAt) }}</span><button class="text-button" @click="detail(row)">{{ forum ? row.locked ? '查看已关闭话题' : '参与讨论' : '查看交换详情' }}<Icon name="arrow"/></button></div></article></div></template>
    <template v-if="tab === 'exchanges'"><div v-if="!exchanges.length" class="empty"><h3>还没有交换记录</h3><p>在资源广场向老乡发起申请，或等待别人回应你的资源。</p></div><article v-for="row in exchanges" :key="row.id" class="panel"><div class="hub-row"><h3>{{ row.resourceTitle }}</h3><span class="tag">{{ exchangeNames[row.status] }}</span></div><p class="meta">资源主人：{{ row.ownerName }} · 申请者：{{ row.requesterName }}</p><p class="prose">{{ row.message }}</p><p class="form-tip">申请者联系方式：{{ row.contact }}<br>资源主人联系方式：{{ row.ownerContact || '未填写' }}</p><p v-if="row.status === 'accepted'" class="status-note">资源主人{{ row.ownerConfirmed ? '已' : '未' }}确认交付 · 申请者{{ row.requesterConfirmed ? '已' : '未' }}确认交付</p><div class="button-row"><template v-if="row.status === 'pending' && row.ownerId === user?.id"><button class="primary" :disabled="busy" @click="changeExchange(row, 'accept')">接受交换</button><button class="outline" :disabled="busy" @click="changeExchange(row, 'reject')">拒绝申请</button></template><button v-if="row.status === 'pending' && row.requesterId === user?.id" class="outline" @click="changeExchange(row, 'cancel')">取消申请</button><button v-if="row.status === 'accepted' && !(row.ownerId === user?.id ? row.ownerConfirmed : row.requesterConfirmed)" class="primary" @click="changeExchange(row, 'confirm')">确认我已完成交付</button></div></article></template>
    <template v-if="tab === 'moderate' && staff"><h3>{{ forum ? '话题管理' : '资源管理' }}</h3><div v-if="!managed.length" class="inline-empty">暂时没有内容需要处理。</div><div v-for="row in managed" :key="row.id" class="record-row"><div><b>{{ row.title }}</b><p>{{ row.authorName }} · {{ row.category }}</p></div><span class="tag">{{ statusNames[row.status] || row.status }}</span><button class="text-button" @click="detail(row)">查看</button><button v-if="row.status !== 'rejected'" class="text-button" @click="review(row, forum ? '/forum/topics' : '/resources')">{{ row.status === 'pending' ? '审核' : row.status === 'hidden' ? '恢复' : '下架' }}</button></div><template v-if="forum"><h3 class="hub-subtitle">回帖管理</h3><div v-if="!managedReplies.length" class="inline-empty">暂时没有回帖。</div><div v-for="row in managedReplies" :key="row.id" class="record-row"><div><b>{{ row.authorName }}</b><p class="prose">{{ row.content }}</p></div><span class="tag">{{ statusNames[row.status] || row.status }}</span><button v-if="row.status !== 'rejected'" class="text-button" @click="review(row, '/forum/replies')">{{ row.status === 'pending' ? '审核回复' : row.status === 'hidden' ? '恢复回复' : '隐藏回复' }}</button></div></template><template v-else><h3 class="hub-subtitle">交换进度</h3><div v-for="row in managedReplies" :key="row.id" class="record-row"><div><b>{{ row.resourceTitle }}</b><p>{{ row.ownerName }} ↔ {{ row.requesterName }}</p></div><span class="tag">{{ exchangeNames[row.status] }}</span></div></template></template>
    <dialog ref="dialog" class="modal" aria-label="论坛与资源操作" @cancel.prevent="close"><div class="modal-inner"><header><h2>{{ modal === 'topic' ? '发起老乡话题' : modal === 'resource' ? '发布交换资源' : modal === 'request' ? '发起交换申请' : modal === 'review' ? '内容审核' : modal === 'confirm' ? '确认操作' : selected.title }}</h2><button class="close-button" aria-label="关闭" :disabled="busy" @click="close">×</button></header><p v-if="error" class="form-error" role="alert">{{ error }}</p>
      <form v-if="modal === 'topic' || modal === 'resource'" @submit.prevent="act(() => api(modal === 'topic' ? '/forum/topics' : '/resources', 'POST', form), '已提交审核，可在我的发布中查看进度')"><label>标题<input v-model="form.title" required minlength="2" maxlength="80"></label><label>分类<select v-model="form.category"><option v-for="value in categories" :key="value">{{ value }}</option></select></label><label v-if="modal === 'topic'">话题正文<textarea v-model="form.content" required minlength="10" maxlength="5000" rows="7"></textarea></label><template v-else><label>我能提供<textarea v-model="form.offering" required minlength="5" maxlength="2000" rows="4" placeholder="说明资源内容、数量或服务范围"></textarea></label><label>我需要<textarea v-model="form.seeking" required minlength="5" maxlength="2000" rows="4" placeholder="说明希望交换的物品、技能或帮助"></textarea></label><label>所在地区<input v-model="form.district" required minlength="2" maxlength="80"></label><label>联系方式（仅审核会员可见）<input v-model="form.contact" maxlength="80"></label></template><p class="form-tip">请勿在公开正文中填写敏感个人信息，发布内容须经过审核。</p><button class="primary full" :disabled="busy">提交审核</button></form>
      <div v-if="modal === 'topicDetail'"><span class="tag">{{ selected.category }} · {{ statusNames[selected.status] || selected.status }}</span><p class="prose">{{ selected.content }}</p><p class="meta">{{ selected.authorName }} · {{ formatTime(selected.createdAt) }}</p><button v-if="!selected.locked && (selected.authorId === user?.id || staff)" class="text-button" @click="open('confirm', { path: '/forum/topics/' + selected.id + '/lock', text: '关闭后将停止接收新回帖，已有内容保留。' })">关闭此话题回复</button><h3 class="hub-subtitle">老乡的回复</h3><div v-if="!replies.length" class="inline-empty">还没有回复，来聊几句吧。</div><article v-for="reply in replies" :key="reply.id" class="reply-row"><div class="hub-row"><b>{{ reply.authorName }}</b><span class="tag">{{ statusNames[reply.status] || reply.status }}</span></div><p class="prose">{{ reply.content }}</p><small v-if="reply.reviewNote">审核说明：{{ reply.reviewNote }}</small></article><p v-if="selected.locked" class="status-note">此话题已关闭回复</p><form v-else-if="selected.status === 'approved'" @submit.prevent="member() && act(() => api('/forum/topics/' + selected.id + '/replies', 'POST', { content: replyContent }), '回复已提交审核', true)"><label>发表回复<textarea v-model="replyContent" required minlength="2" maxlength="2000" rows="3" placeholder="友善交流，认真回应"></textarea></label><button class="primary full" :disabled="busy">提交回复</button></form></div>
      <div v-if="modal === 'resourceDetail'"><span class="tag">{{ selected.category }} · {{ availability[selected.availability] }}</span><h3 class="hub-subtitle">我能提供</h3><p class="prose">{{ selected.offering }}</p><h3>我需要</h3><p class="prose">{{ selected.seeking }}</p><p class="meta">{{ selected.authorName }} · {{ selected.district }}</p><p class="status-note">{{ selected.contact ? '联系方式：' + selected.contact : user?.status === 'approved' ? '发布者未填写联系方式' : '联系方式仅向已审核会员展示' }}</p><div class="button-row"><button v-if="selected.authorId !== user?.id" class="primary" :disabled="selected.availability !== 'available' || selected.status !== 'approved'" @click="member() && open('request', { message: '', contact: '' })">我想交换</button><button v-if="selected.authorId === user?.id && selected.availability === 'available'" class="outline" @click="open('confirm', { path: '/resources/' + selected.id + '/close', text: '关闭后将停止接收申请，所有待处理申请会同步关闭。' })">关闭资源</button></div></div>
      <form v-if="modal === 'request'" @submit.prevent="act(() => api('/resources/' + selected.id + '/requests', 'POST', form), '交换申请已发出，在我的交换查看回应')"><p>{{ selected.title }}</p><label>你的交换方案<textarea v-model="form.message" required minlength="5" maxlength="1000" rows="5" placeholder="介绍可提供的资源，及希望怎样交换"></textarea></label><label>联系方式（仅双方和组织者可见）<input v-model="form.contact" required minlength="2" maxlength="80"></label><button class="primary full" :disabled="busy">发送交换申请</button></form>
      <form v-if="modal === 'review'" @submit.prevent="act(() => api(form.endpoint + '/' + form.id + '/review', 'POST', form), '处理结果已保存')"><h3>{{ form.title || '回帖内容' }}</h3><p class="prose">{{ form.content || form.offering }}</p><p v-if="form.seeking" class="prose">希望交换：{{ form.seeking }}</p><label>审核结果<select v-model="form.status"><option v-if="form.originalStatus !== 'approved'" value="approved">通过 / 恢复展示</option><option v-if="form.originalStatus === 'pending'" value="rejected">退回</option><option v-if="form.originalStatus === 'approved'" value="hidden">隐藏 / 下架</option></select></label><label>处理说明<textarea v-model="form.note" :required="form.status !== 'approved'" :minlength="form.status !== 'approved' ? 2 : 0" maxlength="300" rows="3"></textarea></label><button class="primary full" :disabled="busy">确认处理</button></form>
      <div v-if="modal === 'confirm'"><p class="prose">{{ form.text }}</p><div class="button-row"><button class="outline" @click="close">返回</button><button class="primary" :disabled="busy" @click="act(() => api(form.path, 'POST', form.body), '操作已完成')">确认</button></div></div>
    </div></dialog>
  </section>
</template>
<style scoped>
.hub-toolbar{margin-top:22px}.hub-row{display:flex;justify-content:space-between;align-items:center;gap:15px}.hub-subtitle{margin-top:28px;margin-bottom:15px}.exchange-offer{margin-top:20px;border-left:3px solid #76a89a;padding-left:12px}.exchange-offer small{color:#55927e}.exchange-offer p{font-size:12px;line-height:1.8;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;overflow-wrap:anywhere}.exchange-offer.seek{border-color:#d1b17e}.exchange-offer.seek small{color:#ae8c54}.reply-row{border-bottom:1px solid #e7edef;padding:20px 0}.reply-row b{font-size:13px}.reply-row .prose{margin:12px 0;font-size:13px}
</style>
